{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "urls": {
      "minItems": 1,
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Array of webpage URLs to extract content from (e.g., [\"https://example.com\"])"
    },
    "formats": {
      "description": "Output formats: array of \"markdown\" (text), \"html\" (layout), or \"metadata\" (structured data)",
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["markdown", "html", "metadata"]
      }
    },
    "format": {
      "description": "(Deprecated) Output format - use formats array instead",
      "type": "string",
      "enum": ["markdown", "html"]
    },
    "crawl_timeout": {
      "description": "Optional timeout in seconds (1-60) for page crawling",
      "type": "number",
      "minimum": 1,
      "maximum": 60
    }
  },
  "required": ["urls"],
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "array",
  "items": {
    "type": "object",
    "properties": {
      "url": {
        "type": "string",
        "description": "URL"
      },
      "title": {
        "description": "Title (optional in actual API responses)",
        "type": "string"
      },
      "html": {
        "description": "HTML content",
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "null"
          }
        ]
      },
      "markdown": {
        "description": "Markdown content",
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "null"
          }
        ]
      },
      "metadata": {
        "description": "Page metadata (only when metadata format requested)",
        "anyOf": [
          {
            "type": "object",
            "properties": {
              "site_name": {
                "description": "OpenGraph site name",
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "favicon_url": {
                "type": "string",
                "description": "Favicon URL"
              }
            },
            "required": ["favicon_url"],
            "additionalProperties": false
          },
          {
            "type": "null"
          }
        ]
      }
    },
    "required": ["url"],
    "additionalProperties": false
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "input": {
      "type": "string",
      "minLength": 1,
      "description": "The research question or complex query requiring in-depth investigation and multi-step reasoning. Maximum length: 40,000 characters."
    },
    "research_effort": {
      "default": "standard",
      "description": "Controls how much time and effort the Research API spends on your question. lite: fast answers, standard: balanced (default), deep: thorough, exhaustive: most comprehensive.",
      "type": "string",
      "enum": ["lite", "standard", "deep", "exhaustive"]
    }
  },
  "required": ["input"],
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "output": {
      "type": "object",
      "properties": {
        "content": {
          "type": "string",
          "description": "Comprehensive response with inline citations, formatted in Markdown"
        },
        "content_type": {
          "type": "string",
          "enum": ["text"],
          "description": "The format of the content field"
        },
        "sources": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "url": {
                "type": "string",
                "description": "Source webpage URL"
              },
              "title": {
                "description": "Source webpage title",
                "type": "string"
              },
              "snippets": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Relevant excerpts from the source page used in generating the answer"
              }
            },
            "required": ["url", "snippets"],
            "additionalProperties": false
          },
          "description": "List of web sources used to generate the answer"
        }
      },
      "required": ["content", "content_type", "sources"],
      "additionalProperties": false,
      "description": "The research output containing the answer and sources"
    }
  },
  "required": ["output"],
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "results": {
      "type": "object",
      "properties": {
        "web": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "url": {
                "type": "string",
                "description": "URL"
              },
              "title": {
                "type": "string",
                "description": "Title"
              },
              "description": {
                "type": "string",
                "description": "Description"
              },
              "snippets": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Content snippets"
              },
              "page_age": {
                "description": "Publication timestamp",
                "type": "string"
              },
              "authors": {
                "description": "Authors",
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "thumbnail_url": {
                "description": "Thumbnail image URL",
                "type": "string"
              },
              "favicon_url": {
                "description": "Favicon URL",
                "type": "string"
              },
              "contents": {
                "description": "Live-crawled page content",
                "type": "object",
                "properties": {
                  "html": {
                    "description": "Full HTML content",
                    "type": "string"
                  },
                  "markdown": {
                    "description": "Full Markdown content",
                    "type": "string"
                  }
                },
                "additionalProperties": false
              }
            },
            "required": ["url", "title", "description", "snippets"],
            "additionalProperties": false
          }
        },
        "news": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "title": {
                "type": "string",
                "description": "Title"
              },
              "description": {
                "type": "string",
                "description": "Description"
              },
              "page_age": {
                "type": "string",
                "description": "Publication timestamp"
              },
              "url": {
                "type": "string",
                "description": "URL"
              },
              "thumbnail_url": {
                "description": "Thumbnail image URL",
                "type": "string"
              },
              "contents": {
                "description": "Live-crawled page content",
                "type": "object",
                "properties": {
                  "html": {
                    "description": "Full HTML content",
                    "type": "string"
                  },
                  "markdown": {
                    "description": "Full Markdown content",
                    "type": "string"
                  }
                },
                "additionalProperties": false
              }
            },
            "required": ["title", "description", "page_age", "url"],
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "metadata": {
      "type": "object",
      "properties": {
        "search_uuid": {
          "description": "Unique search request ID",
          "type": "string"
        },
        "query": {
          "type": "string",
          "description": "Query"
        },
        "latency": {
          "type": "number",
          "description": "Latency in seconds"
        }
      },
      "additionalProperties": false
    }
  },
  "required": ["results", "metadata"],
  "additionalProperties": false
}
